WITH district_area AS MATERIALIZED
(SELECT "AdminDistrict".lgd AS lgd, "AdminDistrict"."stateLgd" AS state_lgd, ST_Area(geography("AdminDistrict".geom), false) AS area
FROM "AdminDistrict"
WHERE "AdminDistrict".geom IS NOT NULL)
 INSERT INTO "StateEnvValue" ("stateLgd", "datasetId", variable, "depthOrPeriod", stat, unit, "valueText", districts, "weightedSum", area, total, low, high, resolutions, methods, "datasetDistricts", "datasetArea") SELECT state_series."stateLgd", state_series."datasetId", state_series.variable, state_series."depthOrPeriod", state_series.stat, state_series.unit, state_series."valueText", state_series.districts, state_series."weightedSum", state_series.area, state_series.total, state_series.low, state_series.high, state_series.resolutions, state_series.methods, dataset_coverage.districts AS "datasetDistricts", dataset_coverage.area AS "datasetArea"
FROM (SELECT district_area.state_lgd AS "stateLgd", region_value.dataset_id AS "datasetId", region_value.variable AS variable, region_value.depth_or_period AS "depthOrPeriod", region_value.stat AS stat, region_value.unit AS unit, region_value.value_text AS "valueText", count(*) AS districts, sum(district_area.area * region_value.value) AS "weightedSum", sum(district_area.area) AS area, sum(region_value.value) AS total, min(region_value.value) AS low, max(region_value.value) AS high, array_agg(DISTINCT region_value.resolution) AS resolutions, array_agg(DISTINCT region_value.method) AS methods
FROM (SELECT "DistrictEnvValue"."districtLgd" AS district_lgd, "EnvDataset".code AS dataset_code, "EnvDataset".id AS dataset_id, "DistrictEnvValue".variable AS variable, "DistrictEnvValue"."depthOrPeriod" AS depth_or_period, CAST("DistrictEnvValue".stat AS TEXT) AS stat, CAST("DistrictEnvValue".value AS FLOAT) AS value, "DistrictEnvValue"."valueText" AS value_text, CAST("DistrictEnvValue".unit AS TEXT) AS unit, CAST("DistrictEnvValue".resolution AS TEXT) AS resolution, "DistrictEnvValue".method AS method
FROM "DistrictEnvValue" JOIN "EnvDataset" ON "EnvDataset".id = "DistrictEnvValue"."datasetId"
WHERE ("DistrictEnvValue".variable NOT LIKE 'lithology/_' || '%' ESCAPE '/') UNION ALL SELECT "DistrictGeology"."districtLgd" AS "districtLgd", "EnvDataset".code AS code, "EnvDataset".id AS id, CAST('lithology' AS VARCHAR) AS anon_1, CAST('' AS VARCHAR) AS anon_2, CAST('SHARE' AS TEXT) AS anon_3, CAST("DistrictGeology"."areaShare" AS FLOAT) AS "areaShare", CAST(coalesce("DistrictGeology"."lithologyName", "DistrictGeology".lithology) AS TEXT) AS coalesce_1, CAST('fraction' AS TEXT) AS anon_4, CAST(NULL AS TEXT) AS anon_5, "DistrictGeology".method AS method
FROM "DistrictGeology" JOIN "EnvDataset" ON "EnvDataset".id = "DistrictGeology"."datasetId"
WHERE "DistrictGeology"."areaShare" IS NOT NULL) AS region_value JOIN district_area ON district_area.lgd = region_value.district_lgd
WHERE region_value.value IS NOT NULL AND region_value.stat IN ('DISTRICT_MEAN', 'NORMAL', 'SHARE', 'DENSITY', 'TOTAL', 'COUNT', 'DISTRICT_MIN', 'DISTRICT_MAX') GROUP BY district_area.state_lgd, region_value.dataset_id, region_value.variable, region_value.depth_or_period, region_value.stat, region_value.unit, region_value.value_text) AS state_series JOIN (SELECT held.state_lgd AS state_lgd, held.dataset_id AS dataset_id, count(*) AS districts, sum(held.area) AS area
FROM (SELECT DISTINCT district_area.state_lgd AS state_lgd, region_value.dataset_id AS dataset_id, region_value.district_lgd AS district_lgd, district_area.area AS area
FROM (SELECT "DistrictEnvValue"."districtLgd" AS district_lgd, "EnvDataset".code AS dataset_code, "EnvDataset".id AS dataset_id, "DistrictEnvValue".variable AS variable, "DistrictEnvValue"."depthOrPeriod" AS depth_or_period, CAST("DistrictEnvValue".stat AS TEXT) AS stat, CAST("DistrictEnvValue".value AS FLOAT) AS value, "DistrictEnvValue"."valueText" AS value_text, CAST("DistrictEnvValue".unit AS TEXT) AS unit, CAST("DistrictEnvValue".resolution AS TEXT) AS resolution, "DistrictEnvValue".method AS method
FROM "DistrictEnvValue" JOIN "EnvDataset" ON "EnvDataset".id = "DistrictEnvValue"."datasetId"
WHERE ("DistrictEnvValue".variable NOT LIKE 'lithology/_' || '%' ESCAPE '/') UNION ALL SELECT "DistrictGeology"."districtLgd" AS "districtLgd", "EnvDataset".code AS code, "EnvDataset".id AS id, CAST('lithology' AS VARCHAR) AS anon_1, CAST('' AS VARCHAR) AS anon_2, CAST('SHARE' AS TEXT) AS anon_3, CAST("DistrictGeology"."areaShare" AS FLOAT) AS "areaShare", CAST(coalesce("DistrictGeology"."lithologyName", "DistrictGeology".lithology) AS TEXT) AS coalesce_1, CAST('fraction' AS TEXT) AS anon_4, CAST(NULL AS TEXT) AS anon_5, "DistrictGeology".method AS method
FROM "DistrictGeology" JOIN "EnvDataset" ON "EnvDataset".id = "DistrictGeology"."datasetId"
WHERE "DistrictGeology"."areaShare" IS NOT NULL) AS region_value JOIN district_area ON district_area.lgd = region_value.district_lgd) AS held GROUP BY held.state_lgd, held.dataset_id) AS dataset_coverage ON dataset_coverage.state_lgd = state_series."stateLgd" AND dataset_coverage.dataset_id = state_series."datasetId"
